import React, { useState, useEffect } from 'react';
import './WelcomeModal.css';

const WelcomeModal = ({ isOpen, onClose }) => {
  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h2>Unveiling the Power of Test Case Generation and Execution</h2>
        </div>

        <div className="modal-body">
          <div className="feature-section">
            <div className="feature-box">
              <h3>Introduction to Test Case Generation</h3>
              <p>Discover how AI can help you generate comprehensive test cases automatically.</p>
              <button className="feature-button">Got it</button>
            </div>

            <div className="feature-box">
              <h3>Automated Test Execution</h3>
              <p>Learn about our powerful test execution capabilities.</p>
              <button className="feature-button">Next</button>
            </div>
          </div>
        </div>

        <button className="modal-close" onClick={onClose}>×</button>
      </div>
    </div>
  );
};

export default WelcomeModal;
